Input: {"question": "What is the type of institution Fontbonne is?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0020-f1e0d92938ce:d00", "start": 0, "end": 12, "text": "South Shore."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0020-f1e0d92938ce:d00", "start": 13, "end": 161, "text": "The school has a seven-acre campus with the original building that has been updated over the years to include science, technology and language labs."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0020-f1e0d92938ce:d00", "start": 162, "end": 255, "text": "The building had a facelift in 2010 and installed many energy-saving improvements throughout."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0020-f1e0d92938ce:d00", "start": 256, "end": 312, "text": "Fontbonne Academy boasts a 100% college acceptance rate."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0020-f1e0d92938ce:d00", "start": 313, "end": 410, "text": "The Class of 2013 averaged $175,000 per student in grants and scholarships to four-year colleges."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0020-f1e0d92938ce:d00", "start": 411, "end": 470, "text": "Founded in 1954, the academy takes its name from Mother St."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0020-f1e0d92938ce:d00", "start": 471, "end": 584, "text": "John Fontbonne, who re-established the congregation in France after its suppression during the French Revolution."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0020-f1e0d92938ce:d00", "start": 585, "end": 651, "text": "Under her leadership, the first Sisters came to the United States."}, "D1S9": {"document_number": 1, "doc_id": "ramdocs-0020-f1e0d92938ce:d00", "start": 652, "end": 654, "text": "In"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0020-f1e0d92938ce:d01", "start": 0, "end": 35, "text": "Scholarships to four-year colleges."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0020-f1e0d92938ce:d01", "start": 36, "end": 146, "text": "[citation needed] History Summarize Perspective Founded in 1954, the university takes its name from Mother St."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0020-f1e0d92938ce:d01", "start": 147, "end": 260, "text": "John Fontbonne, who re-established the congregation in France after its suppression during the French Revolution."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0020-f1e0d92938ce:d01", "start": 261, "end": 327, "text": "Under her leadership, the first Sisters came to the United States."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0020-f1e0d92938ce:d01", "start": 328, "end": 486, "text": "In Boston, the congregation taught in archdiocesan parochial schools, and also founded and conducted its own ministries, of which Fontbonne University is one."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0020-f1e0d92938ce:d01", "start": 487, "end": 599, "text": "As a sponsored ministry, Fontbonne University furthers the Sisters' charism — a direct outgrowth of the order's."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0020-f1e0d92938ce:d02", "start": 0, "end": 73, "text": "Fontbonne College as the academy name solely referred to the high school."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0020-f1e0d92938ce:d02", "start": 74, "end": 205, "text": "[9] On October 24, 1970, a group of eight African American women entered the library of Fontbonne Military Base with a common goal."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0020-f1e0d92938ce:d02", "start": 206, "end": 402, "text": "Yolande Nicholson, Antoinette Smith, Rita Hunt, Jeannette Gauda, Collette Lemelle, and three others chained the doors of the library shut and began to do their homework as they occupied the space."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0020-f1e0d92938ce:d02", "start": 403, "end": 490, "text": "Their goal was to see the points in their previously written manifesto come to reality."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0020-f1e0d92938ce:d02", "start": 491, "end": 548, "text": "In their manifesto, they asked for the following changes."}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0020-f1e0d92938ce:d03", "start": 0, "end": 522, "text": "French Literature 5 Honors/6 Honors , Global History Honors , Jazz Choir 1 Honors , Jazz Choir 2 Honors , Jazz Choir 3 Honors , Latin 1 Honors , Latin 2 Honors , Latin 3 Honors , Latin 4 Honors , Masterworks of Literature Honors , Physical Science Honors , Physics Honors , Pre-Calculus Honors , Spanish 2 Honors , Spanish 3 Honors , Spanish 4 Honors , Spanish 5 Honors , US History 1 Honors , US History 2 Honors , US Literature Honors Activities Ambassadors , Anime Club , Cooking Club , Creative Writing Club , Ducks in"}}, "original_cards": [{"doc_id": "ramdocs-0020-f1e0d92938ce:d01", "card_id": "ramdocs-0020-f1e0d92938ce:d01:c0", "entity": "Fontbonne", "scope": "institution type", "claim": "Fontbonne University is a university.", "answer": "university", "quote": "[citation needed] History Summarize Perspective Founded in 1954, the university takes its name from Mother St. John Fontbonne, who re-established the congregation in France after its suppression during the French Revolution. Under her leadership, the first Sisters came to the United States. In Boston, the congregation taught in archdiocesan parochial schools, and also founded and conducted its own ministries, of which Fontbonne University is one. As a sponsored ministry, Fontbonne University furthers the Sisters' charism — a direct outgrowth of the order's.", "original_document_number": 2}], "current_answers": ["academy", "university", "college"], "candidate_answers": [{"candidate_id": "R0", "answer": "academy", "origin": "initial"}, {"candidate_id": "R1", "answer": "university", "origin": "initial"}, {"candidate_id": "R2", "answer": "college", "origin": "coverage_addition"}], "requested_slot_hint": "other"}
